/**
 * A audição do grilo — porte de `componentes/viz/grilo.js`.
 *
 * O "ouvido" do grilo é um tímpano na PERNA dianteira, e ele não escuta de tudo:
 * está sintonizado na frequência do canto da própria espécie. A curva de
 * ressonância tem um pico agudo — fora dele o som chega e não move nada. É o que
 * a cena mostra embaixo: o marcador varrendo a curva até bater no pico.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, limitar, numeroDe, paleta, texto, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const grilo: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const frequencia = numeroDe(valores, 'fq', 0);
    const alvo = numeroDe(info, 'alvo', 4.5);
    const resposta = numeroDe(info, 'resposta', 0);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Um ouvido para um som só');

    // O canto do parceiro, chegando da direita.
    const sx = L * 0.84;
    const sy = A * 0.32;
    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 1.5;
    for (let i = 0; i < 6; i++) {
      const raio = (t * 55 + i * 42) % 260;
      ctx.globalAlpha = 0.55 * (1 - raio / 260);
      ctx.beginPath();
      ctx.arc(sx, sy, raio, Math.PI * 0.6, Math.PI * 1.4);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    texto(ctx, '♪', sx, sy, limitar(A * 0.06, 14, 22), { cor: cor.ouro, peso: 800 });

    // O grilo.
    const gx = L * 0.28;
    const gy = A * 0.4;
    ctx.fillStyle = ok ? '#5a9440' : '#4a7c3a';
    ctx.beginPath();
    ctx.ellipse(gx, gy, 30, 16, 0.1, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(gx + 26, gy - 6, 12, 10, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.arc(gx + 30, gy - 8, 2, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = '#2f4a26';
    ctx.lineWidth = 1.5;
    for (const desvio of [0, 1]) {
      ctx.beginPath();
      ctx.moveTo(gx + 34, gy - 10);
      ctx.quadraticCurveTo(gx + 62, gy - 30, gx + 74 + desvio * 5, gy - 42 + desvio * 8);
      ctx.stroke();
    }

    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(gx - 6, gy + 10);
    ctx.lineTo(gx - 20, gy - 8);
    ctx.lineTo(gx - 32, gy + 26);
    ctx.stroke();

    // A pata dianteira e, nela, o tímpano — o ouvido.
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(gx + 18, gy + 12);
    ctx.lineTo(gx + 24, gy + 34);
    ctx.stroke();

    ctx.fillStyle = ok ? cor.ouro : cor.trilho;
    ctx.beginPath();
    ctx.arc(gx + 24, gy + 22, 5, 0, Math.PI * 2);
    ctx.fill();

    if (ok) {
      ctx.strokeStyle = cor.ouro;
      ctx.lineWidth = 1.5;
      for (let i = 0; i < 3; i++) {
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        ctx.arc(gx + 24, gy + 22, 7 + i * 4 + ((t * 10) % 5), 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }

    // A curva de ressonância. É ela que mostra por que o pico é estreito.
    const baseY = A * 0.86;
    const x0 = L * 0.1;
    const x1 = L * 0.9;
    const altura = A * 0.3;

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x0, baseY);
    ctx.lineTo(x1, baseY);
    ctx.stroke();

    ctx.strokeStyle = ok ? cor.verde : cor.azul;
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let px = x0; px <= x1; px += 3) {
      const fq = 1 + ((px - x0) / (x1 - x0)) * 8;
      const r = 100 / (1 + ((fq - alvo) / 0.85) ** 2);
      const py = baseY - (r / 100) * altura;
      if (px === x0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();

    const marcador = x0 + ((frequencia - 1) / 8) * (x1 - x0);
    ctx.strokeStyle = cor.texto;
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(marcador, baseY);
    ctx.lineTo(marcador, baseY - altura - 2);
    ctx.stroke();
    ctx.setLineDash([]);

    texto(
      ctx,
      `${frequencia.toFixed(1).replace('.', ',')} kHz · ressonância ${Math.round(resposta)}%`,
      L / 2,
      baseY + limitar(A * 0.05, 12, 18),
      limitar(A * 0.042, 9, 13),
      { cor: ok ? cor.verde : cor.fraco, peso: 700 },
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default grilo;
